-- Sales invoice (finance.sales_invoice)
-- GST invoice. Module invoices (RMC, bitumen, bricks, bunk credit) are created here by their billing runs.
create table public.finance_sales_invoice (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  party_id uuid,
  billing_gstin text check (billing_gstin is null or billing_gstin ~ '^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$'),
  place_of_supply text check (place_of_supply ~ '^[0-9]{2}$'),
  shipping_address text,
  reverse_charge boolean not null default false,
  due_date date,
  source_entity text,
  source_ids jsonb,
  taxable_value numeric(14,2),
  gst_amount numeric(14,2),
  tcs_amount numeric(14,2) default 0,
  round_off numeric(14,2) default 0,
  grand_total numeric(14,2) generated always as (taxable_value + gst_amount + coalesce(tcs_amount, 0) + coalesce(round_off, 0)) stored,
  is_interstate boolean not null default false,
  irn text,
  ack_no text,
  ack_date timestamptz,
  signed_qr text,
  eway_bill_no text,
  eway_valid_upto timestamptz,
  vehicle_no text,
  distance_km integer,
  terms text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.finance_sales_invoice (company_id, location_id, doc_date);
alter table public.finance_sales_invoice enable row level security;
create policy admin_read on public.finance_sales_invoice for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.finance_sales_invoice for each row execute function public.erp_touch();
select audit.track('public.finance_sales_invoice');

create table public.finance_sales_invoice_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.finance_sales_invoice on delete cascade,
  line_no integer not null,
  item_id uuid,
  description text,
  hsn_sac text,
  qty numeric(14,3) check (qty > 0),
  uom text,
  rate numeric(14,2),
  discount_pct numeric(7,3) default 0,
  gst_rate numeric(7,3) default 18,
  taxable_value numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100), 2)) stored,
  gst_amount numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * coalesce(gst_rate, 0) / 100, 2)) stored,
  line_total numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * (1 + coalesce(gst_rate, 0) / 100), 2)) stored,
  unique (parent_id, line_no)
);
create index on public.finance_sales_invoice_lines (parent_id);
alter table public.finance_sales_invoice_lines enable row level security;
create policy admin_read on public.finance_sales_invoice_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.finance_sales_invoice_lines');

create function public.finance_sales_invoice_rollup() returns trigger language plpgsql as $$
begin
  new.taxable_value := (select coalesce(sum(taxable_value), 0) from public.finance_sales_invoice_lines where parent_id = new.id);
  new.gst_amount := (select coalesce(sum(gst_amount), 0) from public.finance_sales_invoice_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.finance_sales_invoice for each row execute function public.finance_sales_invoice_rollup();

