-- Purchase invoice (finance.purchase_invoice)
-- Vendor bill, matched against PO and GRN (3-way match) before approval.
create table public.finance_purchase_invoice (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  party_id uuid,
  vendor_invoice_no text,
  vendor_invoice_date date,
  place_of_supply text check (place_of_supply is null or place_of_supply ~ '^[0-9]{2}$'),
  po_id uuid,
  grn_id uuid,
  match_status text default 'not_checked' check (match_status in ('not_checked', 'matched', 'rate_mismatch', 'qty_mismatch', 'no_grn')),
  match_notes text,
  itc_eligible boolean not null default true,
  gstr2b_status text default 'not_checked' check (gstr2b_status in ('not_checked', 'matched', 'partial', 'missing')),
  tds_section text,
  tds_amount numeric(14,2) default 0,
  taxable_value numeric(14,2),
  gst_amount numeric(14,2),
  round_off numeric(14,2) default 0,
  grand_total numeric(14,2) generated always as (taxable_value + gst_amount + coalesce(round_off, 0)) stored,
  due_date date,
  bill_photo text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  unique (company_id, party_id, vendor_invoice_no),
  check (location_id is not null)
);
create index on public.finance_purchase_invoice (company_id, location_id, doc_date);
alter table public.finance_purchase_invoice enable row level security;
create policy admin_read on public.finance_purchase_invoice for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.finance_purchase_invoice for each row execute function public.erp_touch();
select audit.track('public.finance_purchase_invoice');

create table public.finance_purchase_invoice_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.finance_purchase_invoice on delete cascade,
  line_no integer not null,
  item_id uuid,
  description text,
  hsn_sac text,
  qty numeric(14,3) check (qty > 0),
  uom text,
  rate numeric(14,2),
  discount_pct numeric(7,3) default 0,
  gst_rate numeric(7,3) default 18,
  taxable_value numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100), 2)) stored,
  gst_amount numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * coalesce(gst_rate, 0) / 100, 2)) stored,
  line_total numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * (1 + coalesce(gst_rate, 0) / 100), 2)) stored,
  unique (parent_id, line_no)
);
create index on public.finance_purchase_invoice_lines (parent_id);
alter table public.finance_purchase_invoice_lines enable row level security;
create policy admin_read on public.finance_purchase_invoice_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.finance_purchase_invoice_lines');

create function public.finance_purchase_invoice_rollup() returns trigger language plpgsql as $$
begin
  new.taxable_value := (select coalesce(sum(taxable_value), 0) from public.finance_purchase_invoice_lines where parent_id = new.id);
  new.gst_amount := (select coalesce(sum(gst_amount), 0) from public.finance_purchase_invoice_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.finance_purchase_invoice for each row execute function public.finance_purchase_invoice_rollup();

