-- Lead (crm.lead)
-- Every enquiry, from any source, in one list. Assigned by area and business line.
create table public.crm_lead (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  contact_name text,
  mobile text check (mobile is null or mobile ~ '^\+?[0-9]{10,15}$'),
  company_name text,
  business_line text check (business_line in ('rmc', 'bitumen_hotmix', 'bricks', 'infra_contract', 'bunk_credit', 'weighbridge', 'other')),
  source text check (source in ('walk_in', 'phone', 'missed_call', 'whatsapp', 'website', 'indiamart', 'justdial', 'referral', 'site_visit', 'tender_portal', 'existing_customer')),
  stage text default 'new' check (stage in ('new', 'contacted', 'site_visit', 'quote_sent', 'trial', 'negotiation', 'won', 'lost')),
  requirement text,
  quantity numeric(14,3),
  quantity_unit text,
  required_by date,
  site_location text,
  site_address text,
  expected_value numeric(14,2),
  owner_id uuid,
  next_follow_up_at timestamptz,
  lost_reason text check (lost_reason in ('price', 'distance', 'competitor_relationship', 'quality_concern', 'credit_terms', 'project_delayed', 'no_response', 'other')),
  party_id uuid,
  notes text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.crm_lead (company_id, location_id, doc_date);
