-- Quotation (crm.quotation)
-- Rates from the price list; discounts beyond the limit go for approval.
create table public.crm_quotation (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  lead_id uuid,
  party_id uuid,
  customer_name text,
  valid_until date,
  site_distance_km integer,
  transport_charge numeric(14,2) default 0,
  pump_charge numeric(14,2) default 0,
  max_discount_pct numeric(7,3),
  version integer default 1,
  result text default 'open' check (result in ('open', 'accepted', 'rejected', 'expired', 'revised')),
  taxable_value numeric(14,2),
  gst_amount numeric(14,2),
  grand_total numeric(14,2) generated always as (taxable_value + gst_amount + coalesce(transport_charge, 0) + coalesce(pump_charge, 0)) stored,
  terms text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.crm_quotation (company_id, location_id, doc_date);
alter table public.crm_quotation enable row level security;
create policy admin_read on public.crm_quotation for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.crm_quotation for each row execute function public.erp_touch();
select audit.track('public.crm_quotation');

create table public.crm_quotation_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.crm_quotation on delete cascade,
  line_no integer not null,
  item_id uuid,
  description text,
  hsn_sac text,
  qty numeric(14,3) check (qty > 0),
  uom text,
  rate numeric(14,2),
  discount_pct numeric(7,3) default 0,
  gst_rate numeric(7,3) default 18,
  taxable_value numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100), 2)) stored,
  gst_amount numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * coalesce(gst_rate, 0) / 100, 2)) stored,
  line_total numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * (1 + coalesce(gst_rate, 0) / 100), 2)) stored,
  unique (parent_id, line_no)
);
create index on public.crm_quotation_lines (parent_id);
alter table public.crm_quotation_lines enable row level security;
create policy admin_read on public.crm_quotation_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.crm_quotation_lines');

create function public.crm_quotation_rollup() returns trigger language plpgsql as $$
begin
  new.taxable_value := (select coalesce(sum(taxable_value), 0) from public.crm_quotation_lines where parent_id = new.id);
  new.gst_amount := (select coalesce(sum(gst_amount), 0) from public.crm_quotation_lines where parent_id = new.id);
  new.max_discount_pct := (select max(discount_pct) from public.crm_quotation_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.crm_quotation for each row execute function public.crm_quotation_rollup();

