-- Mix design (rmc.mix_design)
-- Approved quantities per m³. Material cost per m³ is worked out from the latest purchase rates.
create table public.rmc_mix_design (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  grade text check (grade in ('M7.5', 'M10', 'M15', 'M20', 'M25', 'M30', 'M35', 'M40', 'M45', 'M50', 'M55', 'M60', 'SCC', 'PQC', 'DLC', 'special')),
  mix_code text,
  version integer default 1,
  wc_ratio numeric(18,4) check (wc_ratio is null or wc_ratio between 0.25 and 0.7),
  slump_target_mm integer,
  slump_tolerance_mm integer default 25,
  max_aggregate_mm integer default 20,
  cement_type text check (cement_type in ('OPC43', 'OPC53', 'PPC', 'PSC')),
  effective_from date,
  material_cost_per_m3 numeric(14,2),
  selling_price_per_m3 numeric(14,2),
  is_active boolean not null default true,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  check (location_id is not null)
);
create index on public.rmc_mix_design (company_id, location_id);
alter table public.rmc_mix_design enable row level security;
create policy admin_read on public.rmc_mix_design for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.rmc_mix_design for each row execute function public.erp_touch();
select audit.track('public.rmc_mix_design');

create table public.rmc_mix_design_materials (
