-- RMC order (rmc.order)
-- Customer order with pour slot. Credit limit is checked before confirming.
create table public.rmc_order (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  party_id uuid,
  site_name text,
  site_location text,
  site_contact text,
  site_mobile text check (site_mobile is null or site_mobile ~ '^\+?[0-9]{10,15}$'),
  distance_km integer,
  grade text check (grade in ('M7.5', 'M10', 'M15', 'M20', 'M25', 'M30', 'M35', 'M40', 'M45', 'M50', 'M55', 'M60', 'SCC', 'PQC', 'DLC', 'special')),
  mix_design_id uuid,
  qty_m3 numeric(14,3) check (qty_m3 > 0),
  element text check (element in ('footing', 'raft', 'column', 'beam', 'slab', 'staircase', 'wall', 'road', 'pcc', 'pile', 'other')),
  pour_start timestamptz,
  pour_rate_m3_hr numeric(18,4) default 15,
  pump text default 'none' check (pump in ('none', 'boom', 'line')),
  slump_mm integer,
  rate_per_m3 numeric(14,2),
  pump_charge numeric(14,2) default 0,
  order_value numeric(14,2) generated always as (round(qty_m3 * coalesce(rate_per_m3, 0) + coalesce(pump_charge, 0), 2)) stored,
  credit_check text default 'not_checked' check (credit_check in ('not_checked', 'ok', 'over_limit', 'overdue', 'override_approved')),
  outstanding_at_order numeric(14,2),
  delivered_m3 numeric(14,3),
  delivery_status text default 'scheduled' check (delivery_status in ('scheduled', 'in_progress', 'completed', 'short_closed', 'cancelled')),
  quotation_id uuid,
  instructions text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.rmc_order (company_id, location_id, doc_date);
alter table public.rmc_order enable row level security;
create policy admin_read on public.rmc_order for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.rmc_order for each row execute function public.erp_touch();
select audit.track('public.rmc_order');

