-- Batch (rmc.batch)
-- One load. Actual weights are compared with the mix design; material is taken out of stock.
create table public.rmc_batch (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  order_id uuid,
  vehicle_id uuid,
  driver_id uuid,
  qty_m3 numeric(14,3) check (qty_m3 > 0 and qty_m3 <= 12),
  batch_start timestamptz default now(),
  batch_end timestamptz,
  water_added_l numeric(18,4) default 0,
  max_deviation_pct numeric(18,4),
  deviation_alert boolean not null default false,
  source text default 'manual' check (source in ('plant_controller', 'manual')),
  controller_batch_no text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.rmc_batch (company_id, location_id, doc_date);
alter table public.rmc_batch enable row level security;
create policy admin_read on public.rmc_batch for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.rmc_batch for each row execute function public.erp_touch();
select audit.track('public.rmc_batch');

create table public.rmc_batch_materials (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.rmc_batch on delete cascade,
  line_no integer not null,
  item_id uuid,
  target_qty numeric(14,3),
  actual_qty numeric(14,3),
  deviation_pct numeric(18,4) generated always as (case when coalesce(target_qty, 0) = 0 then 0 else round((actual_qty - target_qty) / target_qty * 100, 2) end) stored,
  unique (parent_id, line_no)
);
create index on public.rmc_batch_materials (parent_id);
alter table public.rmc_batch_materials enable row level security;
create policy admin_read on public.rmc_batch_materials for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.rmc_batch_materials');

create function public.rmc_batch_rollup() returns trigger language plpgsql as $$
begin
  new.max_deviation_pct := (select max(abs(deviation_pct)) from public.rmc_batch_materials where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.rmc_batch for each row execute function public.rmc_batch_rollup();

