-- Delivery challan (rmc.challan)
-- Printed on Bluetooth printer even offline (number from the phone's reserved block). Signed on the phone at site.
create table public.rmc_challan (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  order_id uuid,
  batch_id uuid,
  party_id uuid,
  grade text check (grade in ('M7.5', 'M10', 'M15', 'M20', 'M25', 'M30', 'M35', 'M40', 'M45', 'M50', 'M55', 'M60', 'SCC', 'PQC', 'DLC', 'special')),
  qty_m3 numeric(14,3),
  vehicle_id uuid,
  left_plant_at timestamptz default now(),
  reached_site_at timestamptz,
  pour_start_at timestamptz,
  pour_end_at timestamptz,
  left_site_at timestamptz,
  site_wait_min integer generated always as (case when reached_site_at is null or pour_start_at is null then null else (extract(epoch from pour_start_at - reached_site_at) / 60)::int end) stored,
  slump_at_site_mm integer,
  returned_m3 numeric(14,3) default 0,
  returned_disposal text check (returned_disposal in ('blocks', 'pcc_yard', 'another_order', 'waste')),
  receiver_name text,
  receiver_signature text,
  receiver_photo text,
  delivered_geo text,
  billing_status text default 'unbilled' check (billing_status in ('unbilled', 'billed', 'not_billable')),
  invoice_id uuid,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
