-- Cube test (rmc.cube_test)
-- Samples cast per pour; results at 7 and 28 days (configurable). Failures alert the plant head.
create table public.rmc_cube_test (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  order_id uuid,
  batch_id uuid,
  grade text check (grade in ('M7.5', 'M10', 'M15', 'M20', 'M25', 'M30', 'M35', 'M40', 'M45', 'M50', 'M55', 'M60', 'SCC', 'PQC', 'DLC', 'special')),
  cast_date date,
  cubes_cast integer default 6,
  lab text default 'own_lab' check (lab in ('own_lab', 'third_party')),
  required_strength numeric(18,4),
  avg_28_day numeric(18,4),
  result text default 'pending' check (result in ('pending', 'pass', 'fail')),
  report_photo text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
