  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.rmc_cube_test on delete cascade,
  line_no integer not null,
  age_days integer,
  test_date date,
  load_kn numeric(18,4),
  cube_size_mm numeric(18,4) default 150,
