-- Weighment ticket (weighbridge.ticket)
-- First and second weight from the scale with camera snapshots. Net goes to the GRN or dispatch automatically.
create table public.weighbridge_ticket (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  ticket_type text check (ticket_type in ('purchase_inward', 'sales_dispatch', 'internal_transfer', 'job_work', 'paid_weighing')),
  vehicle_no text check (vehicle_no = upper(regexp_replace(vehicle_no, '[^A-Za-z0-9]', '', 'g'))),
  vehicle_id uuid,
  vehicle_source text default 'typed' check (vehicle_source in ('anpr', 'rfid', 'typed')),
  driver_name text,
  party_id uuid,
  item_id uuid,
  linked_entity text,
  linked_id text,
  party_challan_no text,
  party_qty_kg numeric(14,3),
  first_weight_kg numeric(18,4),
  first_weight_at timestamptz,
  first_mode text default 'scale' check (first_mode in ('scale', 'manual')),
  first_images text[],
  second_weight_kg numeric(18,4),
  second_weight_at timestamptz,
  second_mode text default 'scale' check (second_mode in ('scale', 'manual')),
  second_images text[],
  gross_kg numeric(18,4) generated always as (greatest(first_weight_kg, second_weight_kg)) stored,
  tare_kg numeric(18,4) generated always as (least(first_weight_kg, second_weight_kg)) stored,
  net_kg numeric(18,4) generated always as (abs(second_weight_kg - first_weight_kg)) stored,
  deduction_kg numeric(18,4) default 0,
  final_kg numeric(18,4) generated always as (abs(second_weight_kg - first_weight_kg) - coalesce(deduction_kg, 0)) stored,
  short_kg numeric(18,4) generated always as (case when party_qty_kg is null or second_weight_kg is null then null else abs(second_weight_kg - first_weight_kg) - coalesce(deduction_kg, 0) - party_qty_kg end) stored,
  standard_tare_kg numeric(18,4),
  tare_alert boolean not null default false,
  minutes_between integer,
  weighing_charge numeric(14,2) default 0,
  ticket_status text default 'first_done' check (ticket_status in ('first_done', 'completed', 'cancelled')),
  manual_reason text,
  operator_id uuid,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.weighbridge_ticket (company_id, location_id, doc_date);
alter table public.weighbridge_ticket enable row level security;
create policy admin_read on public.weighbridge_ticket for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.weighbridge_ticket for each row execute function public.erp_touch();
select audit.track('public.weighbridge_ticket');

