-- Daily progress report (infra.dpr)
-- Site engineer's day: work done with photos, manpower, machines, materials, hindrances.
create table public.infra_dpr (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  project_id uuid,
  weather text check (weather in ('clear', 'cloudy', 'rain', 'heavy_rain', 'very_hot')),
  total_manpower integer,
  hindrances text,
  hindrance_cause text default 'none' check (hindrance_cause in ('none', 'client_decision', 'drawing_pending', 'payment_delay', 'rain', 'material_shortage', 'labour_shortage', 'machine_breakdown', 'local_issue')),
  next_day_plan text,
  photos text[],
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
