create function public.infra_dpr_rollup() returns trigger language plpgsql as $$
begin
  new.total_manpower := (select coalesce(sum(count), 0) from public.infra_dpr_labour where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.infra_dpr for each row execute function public.infra_dpr_rollup();

