-- RA bill (infra.ra_bill)
-- Running account bill: cumulative quantities, deductions as per contract, certified amount tracking.
create table public.infra_ra_bill (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  project_id uuid,
  bill_no integer,
  period_to date,
  this_bill_value numeric(14,2),
  retention numeric(14,2) default 0,
  security_deposit numeric(14,2) default 0,
  mobilisation_recovery numeric(14,2) default 0,
  income_tax_tds numeric(14,2) default 0,
  gst_tds numeric(14,2) default 0,
  labour_cess numeric(14,2) default 0,
  material_recovery numeric(14,2) default 0,
  other_deductions numeric(14,2) default 0,
  gst_amount numeric(14,2) default 0,
  net_payable numeric(14,2) generated always as (coalesce(this_bill_value, 0) + coalesce(gst_amount, 0) - coalesce(retention, 0) - coalesce(security_deposit, 0) - coalesce(mobilisation_recovery, 0) - coalesce(income_tax_tds, 0) - coalesce(gst_tds, 0) - coalesce(labour_cess, 0) - coalesce(material_recovery, 0) - coalesce(other_deductions, 0)) stored,
  certified_value numeric(14,2),
  certification_gap numeric(14,2) generated always as (case when certified_value is null then null else coalesce(this_bill_value, 0) - certified_value end) stored,
  received numeric(14,2) default 0,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.infra_ra_bill (company_id, location_id, doc_date);
alter table public.infra_ra_bill enable row level security;
create policy admin_read on public.infra_ra_bill for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.infra_ra_bill for each row execute function public.erp_touch();
select audit.track('public.infra_ra_bill');

create table public.infra_ra_bill_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.infra_ra_bill on delete cascade,
  line_no integer not null,
  boq_item_id uuid,
  previous_qty numeric(14,3) default 0,
  this_qty numeric(14,3),
  cumulative_qty numeric(14,3) generated always as (coalesce(previous_qty, 0) + this_qty) stored,
  rate numeric(14,2),
  this_amount numeric(14,2) generated always as (round(this_qty * rate, 2)) stored,
  unique (parent_id, line_no)
);
create index on public.infra_ra_bill_lines (parent_id);
alter table public.infra_ra_bill_lines enable row level security;
create policy admin_read on public.infra_ra_bill_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.infra_ra_bill_lines');

create function public.infra_ra_bill_rollup() returns trigger language plpgsql as $$
begin
  new.this_bill_value := (select coalesce(sum(this_amount), 0) from public.infra_ra_bill_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.infra_ra_bill for each row execute function public.infra_ra_bill_rollup();

