-- Shift (bunk.shift)
-- Open with opening readings, close with closing readings and cash. Sale = closing − opening − testing.
create table public.bunk_shift (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  shift_name text check (shift_name in ('morning', 'afternoon', 'night', 'full_day')),
  attendant_id uuid,
  opened_at timestamptz default now(),
  closed_at timestamptz,
  total_litres numeric(14,3),
  sale_value numeric(14,2),
  credit_sales numeric(14,2),
  internal_issues numeric(14,2),
  upi_pos numeric(14,2),
  fleet_card numeric(14,2),
  cash_counted numeric(14,2),
  denominations jsonb,
  expenses_paid numeric(14,2) default 0,
  expected_collection numeric(14,2) generated always as (coalesce(sale_value, 0) - coalesce(credit_sales, 0) - coalesce(internal_issues, 0) - coalesce(upi_pos, 0) - coalesce(fleet_card, 0) - coalesce(expenses_paid, 0)) stored,
  short_excess numeric(14,2) generated always as (coalesce(cash_counted, 0) - (coalesce(sale_value, 0) - coalesce(credit_sales, 0) - coalesce(internal_issues, 0) - coalesce(upi_pos, 0) - coalesce(fleet_card, 0) - coalesce(expenses_paid, 0))) stored,
  remarks text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.bunk_shift (company_id, location_id, doc_date);
alter table public.bunk_shift enable row level security;
create policy admin_read on public.bunk_shift for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.bunk_shift for each row execute function public.erp_touch();
select audit.track('public.bunk_shift');

create table public.bunk_shift_readings (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.bunk_shift on delete cascade,
  line_no integer not null,
  nozzle_id uuid,
  product text check (product in ('MS', 'HSD', 'XP95', 'XG', 'CNG')),
  opening numeric(14,3),
  closing numeric(14,3),
  testing numeric(14,3) default 0,
  rate numeric(14,2),
  closing_photo text,
  sale_litres numeric(14,3) generated always as (case when closing is null then 0 else closing - opening - coalesce(testing, 0) end) stored,
  sale_value numeric(14,2) generated always as (round(case when closing is null then 0 else closing - opening - coalesce(testing, 0) end * coalesce(rate, 0), 2)) stored,
  unique (parent_id, line_no)
);
create index on public.bunk_shift_readings (parent_id);
alter table public.bunk_shift_readings enable row level security;
create policy admin_read on public.bunk_shift_readings for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.bunk_shift_readings');

create table public.bunk_shift_credit (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.bunk_shift on delete cascade,
  line_no integer not null,
  party_id uuid,
  vehicle_no text,
  product text check (product in ('MS', 'HSD', 'XP95', 'XG', 'CNG', 'LUBE')),
  litres numeric(14,3),
  rate numeric(14,2),
  amount numeric(14,2) generated always as (round(litres * coalesce(rate, 0), 2)) stored,
  slip_no text,
  slip_photo text,
  unique (parent_id, line_no)
);
create index on public.bunk_shift_credit (parent_id);
alter table public.bunk_shift_credit enable row level security;
create policy admin_read on public.bunk_shift_credit for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.bunk_shift_credit');

create function public.bunk_shift_rollup() returns trigger language plpgsql as $$
begin
  new.total_litres := (select coalesce(sum(sale_litres), 0) from public.bunk_shift_readings where parent_id = new.id);
  new.sale_value := (select coalesce(sum(sale_value), 0) from public.bunk_shift_readings where parent_id = new.id);
  new.credit_sales := (select coalesce(sum(amount), 0) from public.bunk_shift_credit where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.bunk_shift for each row execute function public.bunk_shift_rollup();

