create function public.bunk_lube_sale_rollup() returns trigger language plpgsql as $$
begin
  new.total := (select coalesce(sum(amount), 0) from public.bunk_lube_sale_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.bunk_lube_sale for each row execute function public.bunk_lube_sale_rollup();

