-- Service job (fleet.service_job)
create table public.fleet_service_job (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  vehicle_id uuid,
  job_type text check (job_type in ('scheduled_service', 'breakdown', 'accident', 'tyre', 'battery', 'electrical', 'body', 'other')),
  complaint text,
  odometer numeric(18,4),
  hour_meter numeric(18,4),
  vendor_id uuid,
  down_from timestamptz,
  down_to timestamptz,
  downtime_hours numeric(18,4) generated always as (case when down_to is null or down_from is null then null else round(extract(epoch from down_to - down_from) / 3600, 1) end) stored,
  labour_cost numeric(14,2) default 0,
  parts_cost numeric(14,2) default 0,
  total_cost numeric(14,2) generated always as (coalesce(labour_cost, 0) + coalesce(parts_cost, 0)) stored,
  photos text[],
  next_service_odometer numeric(18,4),
  next_service_date date,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.fleet_service_job (company_id, location_id, doc_date);
alter table public.fleet_service_job enable row level security;
create policy admin_read on public.fleet_service_job for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.fleet_service_job for each row execute function public.erp_touch();
select audit.track('public.fleet_service_job');

create table public.fleet_service_job_parts (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.fleet_service_job on delete cascade,
  line_no integer not null,
  item_id uuid,
  qty numeric(14,3),
  rate numeric(14,2),
  amount numeric(14,2) generated always as (round(qty * coalesce(rate, 0), 2)) stored,
  serial_no text,
  unique (parent_id, line_no)
);
create index on public.fleet_service_job_parts (parent_id);
alter table public.fleet_service_job_parts enable row level security;
create policy admin_read on public.fleet_service_job_parts for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.fleet_service_job_parts');

create function public.fleet_service_job_rollup() returns trigger language plpgsql as $$
begin
  new.parts_cost := (select coalesce(sum(amount), 0) from public.fleet_service_job_parts where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.fleet_service_job for each row execute function public.fleet_service_job_rollup();

