-- Purchase order (purchase.po)
-- Every line shows the last rates paid across all group companies.
create table public.purchase_po (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  party_id uuid,
  indent_id uuid,
  delivery_by date,
  delivery_address text,
  freight text default 'vendor' check (freight in ('vendor', 'ours', 'extra_at_actuals')),
  payment_days integer default 30,
  rate_contract_ref text,
  taxable_value numeric(14,2),
  gst_amount numeric(14,2),
  grand_total numeric(14,2) generated always as (taxable_value + gst_amount) stored,
  receipt_status text default 'pending' check (receipt_status in ('pending', 'partly', 'complete', 'short_closed')),
  terms text,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.purchase_po (company_id, location_id, doc_date);
alter table public.purchase_po enable row level security;
create policy admin_read on public.purchase_po for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.purchase_po for each row execute function public.erp_touch();
