create table public.purchase_po_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.purchase_po on delete cascade,
  line_no integer not null,
  item_id uuid,
  description text,
  hsn_sac text,
  qty numeric(14,3) check (qty > 0),
  uom text,
  rate numeric(14,2),
  discount_pct numeric(7,3) default 0,
  gst_rate numeric(7,3) default 18,
  taxable_value numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100), 2)) stored,
  gst_amount numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * coalesce(gst_rate, 0) / 100, 2)) stored,
  line_total numeric(14,2) generated always as (round(qty * rate * (1 - coalesce(discount_pct, 0) / 100) * (1 + coalesce(gst_rate, 0) / 100), 2)) stored,
  received_qty numeric(14,3) default 0,
  last_rate numeric(14,2),
  unique (parent_id, line_no)
);
create index on public.purchase_po_lines (parent_id);
alter table public.purchase_po_lines enable row level security;
create policy admin_read on public.purchase_po_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.purchase_po_lines');

create function public.purchase_po_rollup() returns trigger language plpgsql as $$
begin
  new.taxable_value := (select coalesce(sum(taxable_value), 0) from public.purchase_po_lines where parent_id = new.id);
  new.gst_amount := (select coalesce(sum(gst_amount), 0) from public.purchase_po_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.purchase_po for each row execute function public.purchase_po_rollup();

