-- Goods receipt (purchase.grn)
-- What actually arrived. Weighbridge net fills the qty for bulk materials. Stock goes up here.
create table public.purchase_grn (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  party_id uuid,
  po_id uuid,
  vendor_challan_no text,
  vehicle_no text,
  weighbridge_ticket_id uuid,
  qc_status text default 'not_required' check (qc_status in ('not_required', 'pending', 'accepted', 'partly_rejected', 'rejected')),
  photos text[],
  value numeric(14,2),
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.purchase_grn (company_id, location_id, doc_date);
alter table public.purchase_grn enable row level security;
create policy admin_read on public.purchase_grn for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.purchase_grn for each row execute function public.erp_touch();
select audit.track('public.purchase_grn');

create table public.purchase_grn_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.purchase_grn on delete cascade,
  line_no integer not null,
  item_id uuid,
  challan_qty numeric(14,3),
  received_qty numeric(14,3),
  rejected_qty numeric(14,3) default 0,
  accepted_qty numeric(14,3) generated always as (received_qty - coalesce(rejected_qty, 0)) stored,
  short_qty numeric(14,3) generated always as (case when challan_qty is null then 0 else challan_qty - received_qty end) stored,
  rate numeric(14,2),
  batch_no text,
  reject_reason text,
  unique (parent_id, line_no)
);
create index on public.purchase_grn_lines (parent_id);
alter table public.purchase_grn_lines enable row level security;
create policy admin_read on public.purchase_grn_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.purchase_grn_lines');

create function public.purchase_grn_rollup() returns trigger language plpgsql as $$
begin
  new.value := (select coalesce(sum(accepted_qty * coalesce(rate, 0)), 0) from public.purchase_grn_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.purchase_grn for each row execute function public.purchase_grn_rollup();

