-- Stock transfer (purchase.transfer)
-- Move stock between locations. Between group companies it becomes a sale and a purchase automatically.
create table public.purchase_transfer (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  to_location_id uuid,
  to_company_id uuid,
  vehicle_no text,
  eway_bill_no text,
  transit_status text default 'in_transit' check (transit_status in ('in_transit', 'received', 'partly_received')),
  received_at timestamptz,
  received_by uuid,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
