-- Employee (hr.employee)
create table public.hr_employee (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  emp_code text,
  full_name text,
  user_id uuid,
  photo text,
  mobile text check (mobile is null or mobile ~ '^\+?[0-9]{10,15}$'),
  employment_type text check (employment_type in ('permanent', 'contract', 'daily_wage', 'driver', 'operator', 'apprentice')),
  contractor_id uuid,
  department text,
  designation text,
  date_of_joining date,
  date_of_birth date,
  gender text check (gender in ('male', 'female', 'other')),
  aadhaar_last4 text check (aadhaar_last4 is null or aadhaar_last4 ~ '^[0-9]{4}$'),
  pan text check (pan is null or pan ~ '^[A-Z]{5}[0-9]{4}[A-Z]$'),
  uan text,
  esic_no text,
  pf_applicable boolean not null default true,
  esi_applicable boolean not null default false,
  bank_account text,
  ifsc text,
  driving_licence_no text,
  licence_valid_till date,
  shift text default 'general' check (shift in ('general', 'morning', 'afternoon', 'night', 'rotational')),
  weekly_off text default 'sunday' check (weekly_off in ('sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'rotational')),
  pay_basis text default 'monthly' check (pay_basis in ('monthly', 'daily', 'piece_rate')),
  basic numeric(14,2),
  da numeric(14,2) default 0,
  hra numeric(14,2) default 0,
  other_allowance numeric(14,2) default 0,
  daily_wage numeric(14,2),
  monthly_gross numeric(14,2) generated always as (coalesce(basic, 0) + coalesce(da, 0) + coalesce(hra, 0) + coalesce(other_allowance, 0)) stored,
  emp_status text default 'active' check (emp_status in ('active', 'on_notice', 'left', 'absconding')),
  date_of_leaving date,
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, emp_code),
  check (location_id is not null)
);
create index on public.hr_employee (company_id, location_id);
alter table public.hr_employee enable row level security;
create policy admin_read on public.hr_employee for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.hr_employee for each row execute function public.erp_touch();
