-- Payroll run (hr.payroll_run)
-- Monthly salary for a location: attendance, OT, incentives from operations, PF/ESI/PT/TDS, advance recovery.
create table public.hr_payroll_run (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  company_id uuid not null references public.company,
  location_id uuid references public.location,
  doc_no text not null,
  doc_date date not null default current_date,
  status text not null default 'draft' check (status in ('draft', 'submitted', 'approved', 'rejected', 'sent_back', 'cancelled')),
  submitted_at timestamptz,
  approved_at timestamptz,
  approval_request_id uuid references public.approval_request,
  month text check (month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  days_in_month integer,
  gross numeric(14,2),
  pf_employee numeric(14,2),
  pf_employer numeric(14,2),
  esi_employee numeric(14,2),
  esi_employer numeric(14,2),
  pt numeric(14,2),
  tds numeric(14,2),
  advance_recovery numeric(14,2),
  net_pay numeric(14,2),
  device_id text,
  geo text,
  created_by uuid default auth.uid(),
  created_at timestamptz not null default now(),
  updated_by uuid,
  updated_at timestamptz not null default now(),
  unique (company_id, doc_no),
  check (location_id is not null)
);
create index on public.hr_payroll_run (company_id, location_id, doc_date);
alter table public.hr_payroll_run enable row level security;
create policy admin_read on public.hr_payroll_run for select using (public.is_tenant_admin(tenant_id));
create trigger erp_touch before update on public.hr_payroll_run for each row execute function public.erp_touch();
select audit.track('public.hr_payroll_run');

create table public.hr_payroll_run_lines (
  id uuid primary key default gen_random_uuid(),
  tenant_id uuid not null references public.tenant,
  parent_id uuid not null references public.hr_payroll_run on delete cascade,
  line_no integer not null,
  employee_id uuid,
  paid_days numeric(18,4),
  ot_hours numeric(18,4) default 0,
  earned_basic_da numeric(14,2),
  earned_other numeric(14,2),
  ot_amount numeric(14,2) default 0,
  incentive numeric(14,2) default 0,
  gross numeric(14,2) generated always as (coalesce(earned_basic_da, 0) + coalesce(earned_other, 0) + coalesce(ot_amount, 0) + coalesce(incentive, 0)) stored,
  pf_employee numeric(14,2) default 0,
  pf_employer numeric(14,2) default 0,
  esi_employee numeric(14,2) default 0,
  esi_employer numeric(14,2) default 0,
  pt numeric(14,2) default 0,
  tds numeric(14,2) default 0,
  advance_recovery numeric(14,2) default 0,
  net_pay numeric(14,2) generated always as (coalesce(earned_basic_da, 0) + coalesce(earned_other, 0) + coalesce(ot_amount, 0) + coalesce(incentive, 0) - coalesce(pf_employee, 0) - coalesce(esi_employee, 0) - coalesce(pt, 0) - coalesce(tds, 0) - coalesce(advance_recovery, 0)) stored,
  anomalies jsonb,
  unique (parent_id, line_no)
);
create index on public.hr_payroll_run_lines (parent_id);
alter table public.hr_payroll_run_lines enable row level security;
create policy admin_read on public.hr_payroll_run_lines for select using (public.is_tenant_admin(tenant_id));
select audit.track('public.hr_payroll_run_lines');

create function public.hr_payroll_run_rollup() returns trigger language plpgsql as $$
begin
  new.gross := (select coalesce(sum(gross), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.pf_employee := (select coalesce(sum(pf_employee), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.pf_employer := (select coalesce(sum(pf_employer), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.esi_employee := (select coalesce(sum(esi_employee), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.esi_employer := (select coalesce(sum(esi_employer), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.pt := (select coalesce(sum(pt), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.tds := (select coalesce(sum(tds), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.advance_recovery := (select coalesce(sum(advance_recovery), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  new.net_pay := (select coalesce(sum(net_pay), 0) from public.hr_payroll_run_lines where parent_id = new.id);
  return new;
end $$;
create trigger erp_rollup before insert or update on public.hr_payroll_run for each row execute function public.hr_payroll_run_rollup();

